const cfg = $('Config').first().json;
const TZ = 'America/Los_Angeles';
const now = DateTime.now().setZone(TZ);
// EMAIL-FREEZE RULE: date D locks at 14:00 PT on D-1 (customer emails with arrival windows
// go out day-before at ~2pm). Today is NEVER writable. After 14:00, tomorrow is locked too.
const minOffset = now.hour >= 14 ? 2 : 1;
let fromOffset = Number(cfg.fromOffset);
if (fromOffset === -1) fromOffset = minOffset; // auto
if (fromOffset < 1) throw new Error('Never write today or the past (today locked by yesterday 14:00 email).');
if (fromOffset < minOffset && !cfg.lateOverride) throw new Error('Email-freeze guard: earliest writable day is +' + minOffset + ' right now (' + now.toFormat('HH:mm') + ' PT >= 14:00 means tomorrow\'s emails are already sent).');
const from = now.plus({ days: fromOffset });
let to;
const days = Number(cfg.days);
if (days === -1) {
  // WEEK WINDOW: Mon-Thu runs cover the remainder of THIS week (through Sunday).
  // Fri/Sat/Sun runs extend through the end of NEXT week -> Friday's run batch-optimizes
  // the whole week ahead with full freedom (the weekly baseline, per Spencer).
  to = (now.weekday >= 5 ? now.plus({ weeks: 1 }) : now).endOf('week'); // luxon weeks end Sunday
  if (to < from) to = from;
} else {
  if (isNaN(days) || days < 1) throw new Error('Bad days');
  to = now.plus({ days: fromOffset + days - 1 });
}
const fromDate = from.toFormat('yyyy-LL-dd');
const toDate = to.toFormat('yyyy-LL-dd');
const nDays = Math.round(DateTime.fromISO(toDate).diff(DateTime.fromISO(fromDate), 'days').days) + 1;
if (nDays > 16) throw new Error('Window too large: ' + nDays + ' days');
const afterIso = DateTime.fromISO(fromDate + 'T00:00:00', { zone: TZ }).minus({ seconds: 1 }).toUTC().toISO({ suppressMilliseconds: true }); // -1s: Jobber 'after' is exclusive at the exact boundary (anytime visits sit at 00:00)
const beforeIso = DateTime.fromISO(toDate + 'T00:00:00', { zone: TZ }).plus({ days: 1 }).minus({ seconds: 1 }).toUTC().toISO({ suppressMilliseconds: true }); // -1s: Jobber 'before' is inclusive at the exact boundary (next-day anytime visits leaked in)
return [{ json: { fromDate, toDate, afterIso, beforeIso, days: nDays, dryRun: cfg.dryRun, maxOrders: cfg.maxOrders, checkMin: cfg.checkMin, setMin: cfg.setMin, lockTechs: cfg.lockTechs } }];

// Cursor-loop pagination step: accumulate pages in node static data, retry throttles.
const sd = $getWorkflowStaticData('node');
if ($runIndex === 0) { sd.acc = []; sd.cursor = null; sd.retries = 0; }
const r = $input.first().json;
if (r.errors) {
  if (JSON.stringify(r.errors).includes('THROTTLED')) {
    sd.retries = (sd.retries || 0) + 1;
    if (sd.retries > 10) throw new Error('Jobber throttled 10x — giving up.');
    return [{ json: { done: false, retry: true, cursor: sd.cursor } }];
  }
  throw new Error('Jobber error: ' + JSON.stringify(r.errors).slice(0, 400));
}
sd.retries = 0;
const v = r.data && r.data.visits;
if (!v) throw new Error('Unexpected Jobber response: ' + JSON.stringify(r).slice(0, 300));
sd.acc.push(...(v.nodes || []));
sd.cursor = v.pageInfo.endCursor;
if (v.pageInfo.hasNextPage) {
  if (sd.acc.length > 4000) throw new Error('Runaway pagination (>4000 visits)');
  return [{ json: { done: false, retry: false, cursor: sd.cursor, sofar: sd.acc.length } }];
}
const visits = sd.acc; sd.acc = []; sd.cursor = null;
return [{ json: { done: true, visits } }];

const cfg = $('Window').first().json;
const TZ = 'America/Los_Angeles';
const byId = {};
for (const n of ($input.first().json.visits || [])) byId[n.id] = n;
const visits = Object.values(byId);
const toPTDate = iso => DateTime.fromISO(iso, { zone: 'utc' }).setZone(TZ).toFormat('yyyy-LL-dd');
const out = [];
for (const vis of visits) {
  if (vis.isComplete) continue;
  const jn = vis.job && vis.job.jobNumber;
  const visitDate = toPTDate(vis.startAt);
  // Hard clamp: never build an order outside the window, whatever the API boundary does.
  if (visitDate < cfg.fromDate || visitDate > cfg.toDate) { out.push({ json: { kind: 'skipped', reason: 'out-of-window', job: String(jn), visitDate } }); continue; }
  if (jn == null) { out.push({ json: { kind: 'skipped', reason: 'no-job-number', visitId: vis.id, visitDate } }); continue; }
  const users = (vis.assignedUsers && vis.assignedUsers.nodes) || [];
  const tech = (users[0] && users[0].name && users[0].name.full) || null;
  // NOTE: no-tech visits are NOT skipped — Jobber techs may be wrong/missing (Spencer 2026-07-10);
  // the optimizer assigns everyone unless cfg.lockTechs is true.
  const a = vis.property && vis.property.address;
  if (!a || !a.street) { out.push({ json: { kind: 'skipped', reason: 'no-address', job: String(jn), visitDate, tech } }); continue; }
  let visitNum = null;
  try { visitNum = Buffer.from(vis.id, 'base64').toString('utf8').split('/').pop(); } catch (e) {}
  if (!visitNum || !/^\d+$/.test(visitNum)) visitNum = vis.id.replace(/[^a-zA-Z0-9]/g, '').slice(-10);
  const isSet = vis.job.startAt ? toPTDate(vis.job.startAt) === visitDate : false;
  // PIN RULE (window-width sentinel): committed visits have a TIGHT window (optimizer writes
  // +3h; hand-slated similar). Placeholder windows are WIDE (07:00-19:00 backfill = 12h) and
  // 'anytime' (00:00) visits have none -> both float across days. Sets are always pinned.
  const startDt = DateTime.fromISO(vis.startAt, { zone: 'utc' }).setZone(TZ);
  const endDt = vis.endAt ? DateTime.fromISO(vis.endAt, { zone: 'utc' }).setZone(TZ) : null;
  const windowHrs = endDt ? endDt.diff(startDt, 'hours').hours : 99;
  const pinned = isSet || (startDt.toFormat('HH:mm') !== '00:00' && windowHrs <= 6);
  const order = {
    operation: 'SYNC',
    orderNo: jn + '-' + visitNum,
    type: 'T',
    date: visitDate,
    duration: isSet ? Number(cfg.setMin) : Number(cfg.checkMin),
    priority: isSet ? 'C' : 'M',
    location: {
      address: a.street + ', ' + a.city + ', ' + (a.province || 'WA') + ' ' + (a.postalCode || ''),
      // Spencer sees this on the OR map/route list: customer name + job number, human-readable.
      // (orderNo stays the machine ID <job>-<visitNum> for collision-proof matching.)
      locationName: (((vis.title || 'Unknown') + '').trim().replace(/\s+/g, ' ') + ' · #' + jn).slice(0, 60),
      acceptPartialMatch: true,
      acceptMultipleResults: true
    },
    allowedDates: pinned ? { from: visitDate, to: visitDate } : { from: cfg.fromDate, to: cfg.toDate },
    // No weekend work (Spencer 2026-07-10): optimizer may only place orders Mon-Fri.
    // A pinned order dated Sat/Sun becomes unschedulable -> flagged, Spencer re-promises a weekday.
    allowedWeekdays: ['mon', 'tue', 'wed', 'thu', 'fri'],
    notes: 'Jobber job ' + jn + (isSet ? ' (SET)' : pinned ? ' (committed)' : '')
  };
  if (cfg.lockTechs && tech) order.assignedTo = { serial: tech }; // territory lock only when Jobber techs are trusted
  out.push({ json: { kind: 'order', job: String(jn), visitId: vis.id, visitDate, tech, locked: !!(cfg.lockTechs && tech), isSet, pinned, order } });
}
if (!out.length) out.push({ json: { kind: 'empty' } });
return out;

const cfg = $('Window').first().json;
const items = $('Build orders').all().map(i => i.json);
const orders = items.filter(i => i.kind === 'order');
const skipped = items.filter(i => i.kind === 'skipped');
const sets = orders.filter(o => o.isSet);
const pinned = orders.filter(o => o.pinned);
const floating = orders.length - pinned.length;
const L = [];
L.push('WF-1 PUSH (dry) ' + cfg.fromDate + ' -> ' + cfg.toDate);
L.push('Would sync: ' + orders.length + ' orders — ' + pinned.length + ' day-pinned (' + sets.length + ' sets + ' + (pinned.length - sets.length) + ' committed), ' + floating + ' flexible across ' + cfg.fromDate + '..' + cfg.toDate);
const days = {};
for (const o of orders) days[o.visitDate] = (days[o.visitDate] || 0) + 1;
L.push('Per day: ' + Object.keys(days).sort().map(d => d + ':' + days[d]).join('  '));
const wknd = orders.filter(o => DateTime.fromISO(o.visitDate).weekday >= 6);
if (wknd.length) L.push('On Sat/Sun in Jobber: ' + wknd.length + ' (' + wknd.filter(w => w.pinned).length + ' pinned -> will flag unschedulable; the rest shift to Mon-Fri)');
const techs = {};
for (const o of orders) { const t = o.tech || '(unassigned)'; techs[t] = (techs[t] || 0) + 1; }
L.push('Jobber tech (informational' + (orders[0] && orders[0].locked ? ', LOCKED' : ', NOT locked — optimizer assigns') + '): ' + Object.keys(techs).sort().map(t => t + ':' + techs[t]).join('  '));
if (skipped.length) L.push('Skipped ' + skipped.length + ': ' + skipped.slice(0, 20).map(s => '[' + s.reason + ' job ' + (s.job || '?') + ' ' + s.visitDate + ']').join(' '));
if (sets.length) L.push('Sets: ' + sets.map(s => 'job ' + s.job + ' ' + s.visitDate + ' (' + s.tech + ')').join(', '));
return [{ json: { title: 'WF-1 push ' + cfg.fromDate + '->' + cfg.toDate, mode: 'PUSH-DRY', days: Number(cfg.days), scheduled: orders.length, timeFixed: 0, errors: 0, text: L.join('\n') } }];

const cfg = $('Window').first().json;
const max = Number(cfg.maxOrders || 0);
const orders = $('Build orders').all().map(i => i.json).filter(i => i.kind === 'order');
const capped = max > 0 ? orders.slice(0, max) : [];
if (!capped.length) return [{ json: { noop: true, wouldCreate: orders.length } }];
return capped.map(o => ({ json: o }));

const cfg = $('Window').first().json;
const all = $('Build orders').all().map(i => i.json);
const skipped = all.filter(i => i.kind === 'skipped');
const emitted = $('Emit orders').all().map(i => i.json);
let results = [];
try { results = $('Create order').all().map(i => i.json); } catch (e) {}
if (emitted.length === 1 && emitted[0].noop) {
  return [{ json: { title: 'WF-1 push ' + cfg.fromDate + '->' + cfg.toDate, mode: 'PUSH-LIVE', days: Number(cfg.days), scheduled: 0, timeFixed: 0, errors: 0, text: 'NOOP: maxOrders=0 or no orders. Would sync ' + emitted[0].wouldCreate + '. Raise maxOrders for a real push.' } }];
}
let ok = 0, failed = 0; const errs = [];
for (let i = 0; i < emitted.length; i++) {
  const r = results[i] || {};
  if (r.success) ok++;
  else { failed++; errs.push('job ' + emitted[i].job + ': ' + (r.code || '') + ' ' + (r.message || JSON.stringify(r).slice(0, 120))); }
}
const sets = emitted.filter(o => o.isSet).length;
const pinnedN = emitted.filter(o => o.pinned).length;
const L = [];
L.push('WF-1 PUSH LIVE ' + cfg.fromDate + ' -> ' + cfg.toDate);
L.push('Orders synced: ' + ok + ' ok, ' + failed + ' failed, of ' + emitted.length + ' emitted (' + pinnedN + ' day-pinned incl ' + sets + ' sets, ' + (emitted.length - pinnedN) + ' flexible)');
if (skipped.length) L.push('Skipped ' + skipped.length + ': ' + skipped.slice(0, 20).map(s => '[' + s.reason + ' job ' + (s.job || '?') + ']').join(' '));
if (errs.length) L.push('Errors: ' + errs.slice(0, 15).join(' | '));
return [{ json: { title: 'WF-1 push ' + cfg.fromDate + '->' + cfg.toDate, mode: 'PUSH-LIVE', days: Number(cfg.days), scheduled: ok, timeFixed: 0, errors: failed, text: L.join('\n') } }];
